package goshopee

type Content struct {
	ShopId     int64   `json:"shop_id"`            // [Required] <p>Shop identifier of the target shop to be queried.</p><p>Limitations:</p><p>- Required for every shop object in content_list.</p><p>- Must belong to the specified principal_id.</p>
	ContentIds []int64 `json:"content_ids"`        // [Required] <p>List of content IDs under the specified shop_id to be queried.</p><p><br /></p><p>Limitations:</p><p>- Required for every shop object in content_list.</p><p>- Must contain 1 to 100 values.</p><p>- Duplicate content_id values are not allowed within the request.</p>
	Currency   *string `json:"currency,omitempty"` // [Optional] <p>Currency used for amount-based metrics for the specified content items.<br /><br />Limitations:</p><p>- Optional for every object in content_list.</p><p>- Supported values are LOCAL and USD.</p><p>- Invalid currency values are rejected as invalid_parameter.</p><p>- Defaults to USD when omitted.</p></p>
}
type Details struct {
	Region               string  `json:"region"`                 // [Required] <p>Region code of the shop that owns this video.</p>
	Currency             string  `json:"currency"`               // [Required] <p>Currency code used for all amount-based metrics of this video item.</p>
	ShopId               int64   `json:"shop_id"`                // [Required] <p>Shop identifier that owns this video.</p>
	ShopName             string  `json:"shop_name"`              // [Required] <p>Shop name that owns this video.</p>
	VideoId              int64   `json:"video_id"`               // [Required] <p>Video identifier.</p>
	VideoName            string  `json:"video_name"`             // [Required] <p>Video name.</p>
	TotalViews           int64   `json:"total_views"`            // [Required] <p>Total views from this video.</p>
	UniqueViewers        int64   `json:"unique_viewers"`         // [Required] <p>Number of video viewers in the selected period. Note: This data is unavailable when you select by month, by quarter, by year, customize date, or a non-full weekly range.</p>
	VideoDuration        float64 `json:"video_duration"`         // [Required] <p>Video duration in minutes.</p>
	AverageViewsDuration float64 `json:"average_views_duration"` // [Required] <p>Average viewing duration per video in minutes.</p>
	Likes                int64   `json:"likes"`                  // [Required] <p>Number of Like clicks from this video.</p>
	Comments             int64   `json:"comments"`               // [Required] <p>Number of comments generated from this video.</p>
	Share                int64   `json:"share"`                  // [Required] <p>Number of shares created from this video.</p>
	TotalUniqueBuyers    int64   `json:"total_unique_buyers"`    // [Required] <p>Number of unique buyers who placed order from this video. Note: This data is unavailable when you select by month, by quarter, by year, customize date, or a non-full weekly range.</p>
	AtcUnits             int64   `json:"atc_units"`              // [Required] <p>Number of Add To Cart button clicks for all products in the orange bag during this video.</p>
	UnitsSold            int64   `json:"units_sold"`             // [Required] <p>Number of items sold from placed orders during this video.</p>
	Orders               int64   `json:"orders"`                 // [Required] <p>Number of placed orders (paid and unpaid) during this video, including cancelled orders.</p>
	Sales                float64 `json:"sales"`                  // [Required] <p>Value of placed orders (paid and unpaid) from this video in the period, reflecting the sales amount received by sellers after deducting seller rebates. Note: This value includes sales from cancelled and return/refund orders.</p>
	ConversionRate       float64 `json:"conversion_rate"`        // [Required] <p>Video orders / total video views.</p>
}
type GetClipVideoPerformanceRequest struct {
	Cursor      *int64  `json:"cursor,omitempty"`     // [Optional] <p>Zero-based offset of the first detail record to return.</p><p><br /></p><p>Limitations:</p><p>- Only supported when video_list is omitted or an empty array.</p><p>- Default value is 0.</p><p>- Must be greater than or equal to 0.</p>
	EndDate     string  `json:"end_date"`             // [Required] <p>End date of the requested period in YYYY-MM-DD format.<br /><br />Limitations:<br /><br />- Must use the YYYY-MM-DD format.<br /><br />- Must be a valid calendar date.<br /><br />- Must not be earlier than start_date.<br /><br />- Validation is based on the requested timezone.<br /><br />- For customize, end_date must not be later than the day before the current day in the requested timezone. The inclusive date range from start_date to end_date must not exceed 366 days.<br /><br />- For day, end_date must equal start_date.<br /><br />- For week, end_date must be within the selected week range: from start_date (Sunday) to the end of that Sunday-to-Saturday week, or to the latest selectable day if the week extends beyond today. Formally: startDate ≤ endDate ≤ min(startDate + 6 days, today - 1 day).<br /><br />- For month, end_date must be within the selected month: from the 1st day of the month to the last calendar day of that month, or to the latest selectable day for the current month. Formally: startDate ≤ endDate ≤ min(month end, today - 1 day).<br /><br />- For quarter, end_date must be within the selected quarter: from the 1st day of the quarter to the last calendar day of that quarter, or to the latest selectable day for the current quarter. Formally: startDate ≤ endDate ≤ min(quarter end, today - 1 day).<br /><br />- For year, end_date must be within the selected year: from January 1st to December 31st of that year, or to the latest selectable day for the current year. Formally: startDate ≤ endDate ≤ min(Dec 31, today - 1 day).</p>
	Granularity string  `json:"granularity"`          // [Required] <p>Aggregation granularity that determines the validation rules for the requested date range and the reporting period.</p><p><br /></p><p>Limitations:</p><p>- Supported values are customize, day, week, month, quarter, and year.</p><p>- customize is validated as a free date range.</p><p>- day represents a single calendar day.</p><p>- week requires a Sunday-based calendar week.</p><p>- month requires a calendar month range.</p><p>- quarter requires a calendar quarter range.</p><p>- year requires a calendar year range.</p><p>- Any other value is rejected as invalid_parameter.</p>
	PageSize    *int64  `json:"page_size,omitempty"`  // [Optional] <p>Number of detail records to return in the current response page.</p><p><br /></p><p>Limitations:</p><p>- Only supported when video_list is omitted or an empty array.</p><p>- Default value is 100.</p><p>- Must be between 1 and 200, inclusive.</p>
	StartDate   string  `json:"start_date"`           // [Required] <p>Start date of the requested period in YYYY-MM-DD format.<br /><br />Limitations:</p><p>- Must use the YYYY-MM-DD format.</p><p>- Must be a valid calendar date.</p><p>- Must not be later than end_date.</p><p>- Validation is based on the requested timezone.</p><p>- The earliest selectable date is calculated as: current day in timezone - 1 day - 2 years.</p><p>- The exact boundary rules depend on granularity:</p><p>-- For customize, start_date must not be earlier than the earliest selectable date.</p><p>-- For day, start_date must equal end_date.</p><p>-- For week, start_date must be a Sunday.</p><p>-- For month, start_date must be the first day of the month.</p><p>-- For quarter, start_date must be the first day of the quarter.</p><p>-- For year, start_date must be the first day of the year.</p>
	Timezone    string  `json:"timezone"`             // [Required] <p>Timezone used for date boundary calculation, selectable date validation, and timestamp conversion.<br /><br />Limitations:</p><p>- Enum values: [\"GMT+7\", \"GMT+8\", \"GMT-3\"]</p><p>- The API internally normalizes the open API timezone value for video metric queries.</p><p>- All date validation rules are evaluated in the requested timezone.</p>
	VideoList   []Video `json:"video_list,omitempty"` // [Optional] <p>List of video clip query targets.</p><p><br /></p><p>Limitations:</p><p>- Must contain at least one object.</p><p>- Must contain at most 100 objects.</p><p>- Every shop_id must belong to the specified principal_id.</p><p>- Duplicate shop_id values are rejected.</p><p>- Each object must provide a non-empty video_ids list.</p><p>- Null video_id values are rejected.</p><p>- Duplicate video_id values across the whole request are rejected.</p><p>- The total number of unique video_ids across the whole request must not exceed 100.</p></p>
}
