type GetClipVideoPerformanceResponseData struct {
	Summary    []Summary `json:"summary"`     // [Required] <p>Aggregated summary metrics for the requested date range, representing the overall performance of the selected videos.</p><p><br /></p><p>Note:</p><p>- unique_viewers and total_unique_buyers are unavailable for customize, month, quarter, year, and non-full-week weekly ranges.</p></p>
	Details    []Details `json:"details"`     // [Required] <p>List of video-level detail records that returns performance metrics for each selected video within the requested date range.</p><p><br /></p><p>Details are sorted by shop_id and then video_id in ascending order.</p><p>- unique_viewers and total_unique_buyers are unavailable for customize, month, quarter, year, and non-full-week weekly ranges.</p></p>
	NextCursor int64     `json:"next_cursor"` // [Required] <p>Offset to be used in the next request for fetching the next page of detail records.</p><p><br /></p><p>Notes:</p><p>- Returned only when video_list is omitted or an empty array.</p><p>- Calculated as cursor + returned_detail_count.</p><p>- If returned_detail_count is less than page_size, it indicates there may be no more records.</p><p>- If the request is already beyond the end of the result set, the API returns 0 detail records and next_cursor remains equal to the input cursor.</p>
}
